  "type": "object",
  "properties": {
    "revision_id": {
      "type": "string",
      "pattern": "^[a-f0-9]{32}$",
      "description": "ID-ul fișei globale; nu acordă administrarea articolului comercial."
    },
    "fields": {
      "type": "array",
      "maxItems": 6,
      "items": {
        "enum": [
          "name",
          "ingredients",
          "allergens",
