import json, urllib.request, urllib.parse, urllib.error

headers = {'Accept': 'application/json', 'Authorization': 'Bearer YOUR_ACCESS_TOKEN', 'Idempotency-Key': 'exemplu-externalConflictDecision-001', 'Content-Type': 'application/json'}
payload = json.loads('{"state": "accepted", "reason": "exemplu"}')
data = json.dumps(payload).encode("utf-8")
request = urllib.request.Request('https://openaliment.ro/api/v2/manage/source-conflicts/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa/decisions', data=data, headers=headers, method='POST')
try:
    with urllib.request.urlopen(request, timeout=15) as response:
        print(json.load(response))
except urllib.error.HTTPError as error:
    print(error.code, error.read().decode("utf-8", errors="replace"))
    raise
