curl --fail-with-body -X POST https://openaliment.ro/api/v2/manage/items/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa/sources/openfoodfacts/publications \
  -H 'Accept: application/json' \
  -H 'Authorization: Bearer YOUR_ACCESS_TOKEN' \
